package main

// ❌ OLD: A hand-rolled stop channel. It only signals ONE level; if
// the worker spawns sub-workers, you must thread the stop channel to
// each of them manually. No deadline support, no values, and if you
// forget to close(stop), the goroutine leaks forever.
func worker(stop <-chan struct{}) {
	for {
		select {
		case <-stop:
			return // ❌ OLD: only this goroutine stops
		default:
			doWork()
		}
	}
}

func main() {
	stop := make(chan struct{}) // ❌ OLD
	go worker(stop)
	// ...later:
	close(stop) // ❌ OLD: sub-workers spawned by worker() never hear this
}

